/**
 * Damage output for Land Mines and Ultimate Weapons.
 *
 * Derived from `damageFormula.ts` in tower-idle-toolkit by skye (ISC).
 * See NOTICE at the package root.
 */

export type AbilityDamageInput = {
  /**
   * The percentage shown on the ability's tooltip (on the button itself for
   * Land Mines). If it reads 321%, pass `321`. Smart Missiles show a multiplier
   * rather than a percentage — multiply by 100 first.
   */
  damagePercent: number
  /** Workshop Damage, as shown in the Attack tab mid-run. */
  damage: number
  /** Workshop Crit Factor, as shown in the Attack tab mid-run. */
  critFactor: number
  /** Workshop Crit Chance, as shown in the Attack tab mid-run. */
  critChance: number
  /** Workshop Super Crit Mult, as shown in the Attack tab mid-run. */
  superCritMult: number
  /** Workshop Super Crit Chance, as shown in the Attack tab mid-run. */
  superCritChance: number
}

/**
 * Average damage per hit, with crit and super-crit folded in.
 *
 * Every input is the value the game displays mid-run, i.e. already including
 * perks, cards and labs. Don't apply those yourself.
 */
export function abilityDamage({
  damagePercent,
  damage,
  critFactor,
  critChance,
  superCritMult,
  superCritChance,
}: AbilityDamageInput): number {
  return (
    (damagePercent / 100)
    * damage
    * (1 + (critFactor * critChance) / 100)
    * (1 + (((superCritMult * critChance) / 100) * superCritChance) / 100)
  )
}
